/*
 * nrfx_config.h — micro:bit v2.2 (nRF52833) 向け nrfx 構成
 *
 * 使用するドライバのみ有効化。
 */

#ifndef NRFX_CONFIG_H__
#define NRFX_CONFIG_H__

/* GPIO / GPIOTE */
#define NRFX_GPIOTE_ENABLED 1
#define NRFX_GPIOTE0_ENABLED 1
#define NRFX_GPIOTE_DEFAULT_CONFIG_IRQ_PRIORITY 7

/* PWM (Speaker) */
#define NRFX_PWM_ENABLED 1
#define NRFX_PWM0_ENABLED 1
#define NRFX_PWM_DEFAULT_CONFIG_IRQ_PRIORITY 7

/* SAADC (Mic) */
#define NRFX_SAADC_ENABLED 1
#define NRFX_SAADC_DEFAULT_CONFIG_IRQ_PRIORITY 7

/* TWIM (I2C: accelerometer, magnetometer) */
#define NRFX_TWIM_ENABLED 1
#define NRFX_TWIM0_ENABLED 1
#define NRFX_TWIM_DEFAULT_CONFIG_IRQ_PRIORITY 7

/* TEMP (on-chip temperature) */
#define NRFX_TEMP_ENABLED 1
#define NRFX_TEMP_DEFAULT_CONFIG_IRQ_PRIORITY 7

/* TIMER (LED scan) */
#define NRFX_TIMER_ENABLED 1
#define NRFX_TIMER1_ENABLED 1
#define NRFX_TIMER_DEFAULT_CONFIG_IRQ_PRIORITY 7

/* API version */
#define NRFX_CONFIG_API_VER_MAJOR 4
#define NRFX_CONFIG_API_VER_MINOR 0
#define NRFX_CONFIG_API_VER_MICRO 0

#endif /* NRFX_CONFIG_H__ */
